(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.018-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.025+t*0.4)*8 + Math.cos((y+w1y)*0.02-t*0.35)*6;
  const w2y = Math.cos((y+w1y)*0.025-t*0.38)*8 + Math.sin((x+w1x)*0.022+t*0.42)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [60+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.6+1)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.45+2)*60,200+Math.sin(t*0.65+4)*60,0.085,1.8,1.05]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,wt]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*wt;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*wt;
    hrm+=Math.sin(d*f*1.5-t*sp*1.3+0.8)*wt*0.35+Math.sin(d*f*2.1+t*sp*0.9-1.2)*wt*0.15;
  }
  const n=src.length,act=aS/n,inh=iS/n,hr=hrm/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.06+t*0.5)*Math.cos(sy*0.05-t*0.4)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08+ang*2-t*2.1)*0.2;
  const rad=Math.sin(dist*0.03-t*0.8)*0.15;
  const rd=act-inh*0.7+bg*0.3+sp1+sp2+rad+hr*0.25;
  const reaction=Math.tanh(rd*2.2);
  const cs=0.12,gx=Math.floor(sx*cs),gy=Math.floor(sy*cs);
  let mD=99,sD=99;
  for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
    const px=(gx+dx)/cs,py=(gy+dy)/cs;
    const nx=px+Math.sin(py*0.7+t*0.3)*4+Math.cos(px*0.5+t*0.2)*3;
    const ny=py+Math.cos(px*0.6-t*0.25)*4+Math.sin(py*0.4-t*0.15)*3;
    const d=Math.sqrt((sx-nx)**2+(sy-ny)**2);
    if(d<mD){sD=mD;mD=d;}else if(d<sD)sD=d;
  }
  const cellN=Math.tanh(((sD-mD)*0.15-0.5)*2)*0.25;
  const blend=reaction*0.7+cellN*0.3;
  const edge=1.0-Math.exp(-Math.abs(blend)*5)*0.15;
  const v=blend*0.5+0.5;
  const pal=[[10,14,52],[14,38,78],[12,82,105],[18,138,132],[65,182,148],[175,195,82],[210,165,52],[208,112,58],[185,68,65],[142,46,72],[85,28,68],[35,16,56],[10,14,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const glow=Math.abs(reaction)>0.85?1.2:Math.abs(reaction)>0.65?1.12:1.0;
  const m=lum*glow*edge;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0];
}
